import { createHash } from 'node:crypto';

import type { IconRecord } from './model.js';
import { validateIconCatalog } from './model.js';

export const generatedArtifactNames = [
  'runtime-catalog.ts',
  'review-index.html',
  'source-manifest.json',
  'output-manifest.json',
] as const;

export type GeneratedArtifactName = (typeof generatedArtifactNames)[number];
export type GeneratedIconArtifacts = Readonly<Record<GeneratedArtifactName, string>>;

export interface ArtifactDrift {
  readonly artifact: string;
  readonly kind: 'changed' | 'missing' | 'unexpected';
}

function compareText(left: string, right: string): number {
  return left < right ? -1 : left > right ? 1 : 0;
}

function canonicalValue(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(canonicalValue);
  if (typeof value !== 'object' || value === null) return value;

  return Object.fromEntries(
    Object.keys(value)
      .sort(compareText)
      .map((key) => [key, canonicalValue((value as Record<string, unknown>)[key])]),
  );
}

function canonicalJson(value: unknown): string {
  return `${JSON.stringify(canonicalValue(value), undefined, 2)}\n`;
}

function sha256(value: string): string {
  return createHash('sha256').update(value, 'utf8').digest('hex');
}

function runtimeCatalogSource(catalog: readonly IconRecord[]): string {
  const records = catalog.map(({ id, direction, primitives }) => ({
    name: id,
    direction,
    primitives,
  }));

  return [
    '// Generated by the private Phase 5D-A proof. Do not edit.',
    '// This candidate is not a production package export.',
    '',
    `export const generatedIconCatalog = ${JSON.stringify(records, undefined, 2)} as const;`,
    '',
    "export type GeneratedIconName = (typeof generatedIconCatalog)[number]['name'];",
    '',
  ].join('\n');
}

function pathData(icon: IconRecord): string {
  return icon.primitives
    .filter((primitive) => primitive.type === 'path')
    .map((primitive) =>
      primitive.commands
        .map((command) => {
          switch (command.command) {
            case 'move-to':
              return `M ${command.x} ${command.y}`;
            case 'line-to':
              return `L ${command.x} ${command.y}`;
            case 'arc-to':
              return `A ${command.radiusX} ${command.radiusY} ${command.rotation} ${command.largeArc ? 1 : 0} ${command.sweep ? 1 : 0} ${command.x} ${command.y}`;
            case 'close-path':
              return 'Z';
          }
        })
        .join(' '),
    )
    .join(' ');
}

function symbolMarkup(icon: IconRecord): string {
  const primitives = icon.primitives
    .map((primitive) => {
      if (primitive.type === 'path') {
        return `<path d="${pathData({ ...icon, primitives: [primitive] })}" fill="${primitive.fill}" stroke="${primitive.stroke}" />`;
      }
      return `<circle cx="${primitive.centerX}" cy="${primitive.centerY}" r="${primitive.radius}" fill="${primitive.fill}" stroke="${primitive.stroke}" />`;
    })
    .join('');
  return `<symbol id="p5d-icon-${icon.id}" viewBox="0 0 24 24">${primitives}</symbol>`;
}

function decorativeSvg(icon: IconRecord, size: string, direction: 'ltr' | 'rtl'): string {
  return `<figure class="sample" data-size="${size}" dir="${direction}"><svg class="icon icon--${size}" data-direction="${icon.direction}" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><use href="#p5d-icon-${icon.id}" /></svg><figcaption>${size}, ${direction.toUpperCase()}</figcaption></figure>`;
}

function reviewCard(icon: IconRecord): string {
  const samples = ['compact', 'standard', 'prominent']
    .flatMap((size) =>
      (['ltr', 'rtl'] as const).map((direction) => decorativeSvg(icon, size, direction)),
    )
    .join('');
  return `<article class="icon-card" data-icon="${icon.id}" data-direction="${icon.direction}"><header><h3>${icon.id}</h3><span>${icon.direction}</span></header><div class="sample-grid">${samples}</div><dl><div><dt>Category</dt><dd>${icon.category}</dd></div><div><dt>Accessible use</dt><dd>${icon.accessibleUse}</dd></div></dl></article>`;
}

function themeReview(catalog: readonly IconRecord[], theme: 'light' | 'dark'): string {
  return `<section class="theme theme--${theme}" data-theme="${theme}" aria-labelledby="${theme}-heading"><h2 id="${theme}-heading">${theme[0]!.toUpperCase()}${theme.slice(1)} review</h2><div class="catalog">${catalog.map(reviewCard).join('')}</div></section>`;
}

function reviewIndexHtml(catalog: readonly IconRecord[]): string {
  const fallback = catalog[0]!;
  const close = catalog.find(({ id }) => id === 'close') ?? fallback;
  const menu = catalog.find(({ id }) => id === 'menu') ?? fallback;
  const refresh = catalog.find(({ id }) => id === 'refresh') ?? fallback;
  const arrow =
    catalog.find(({ id }) => id === 'arrow-inline-start') ??
    catalog.find(({ direction }) => direction === 'mirrors-in-rtl') ??
    fallback;
  const symbols = catalog.map(symbolMarkup).join('');

  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1" />
<title>Phase 5D-A icon review index</title>
<style>
:root{font-family:ui-sans-serif,system-ui,sans-serif;color-scheme:light dark;line-height:1.5}*{box-sizing:border-box}body{margin:0;background:#101722;color:#edf3fb}main{display:grid;gap:2rem;max-inline-size:96rem;margin-inline:auto;padding:clamp(1rem,3vw,3rem)}h1,h2,h3,p{margin-block-start:0}h1{font-size:clamp(1.75rem,4vw,3rem)}.intro{max-inline-size:70ch}.theme{padding:clamp(1rem,2vw,2rem);border:2px solid currentColor;border-radius:1rem}.theme--light{background:#f5f8fb;color:#172231}.theme--dark{background:#111a27;color:#edf3fb}.catalog{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,18rem),1fr));gap:1rem}.icon-card{min-inline-size:0;padding:1rem;border:1px solid currentColor;border-radius:.75rem}.icon-card header{display:flex;flex-wrap:wrap;justify-content:space-between;gap:.5rem}.icon-card h3{overflow-wrap:anywhere}.icon-card header span{font-family:ui-monospace,monospace;font-size:.75rem}.sample-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.5rem}.sample{display:grid;place-items:center;gap:.25rem;min-block-size:4.75rem;margin:0;padding:.5rem;border:1px dashed currentColor;border-radius:.5rem}.sample figcaption{font-size:.7rem}.icon{display:block;overflow:visible;color:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round;transform-box:fill-box;transform-origin:center}.icon--compact{inline-size:1rem;block-size:1rem}.icon--standard{inline-size:1.5rem;block-size:1.5rem}.icon--prominent{inline-size:2.5rem;block-size:2.5rem}[dir="rtl"] .icon[data-direction="mirrors-in-rtl"]{transform:scaleX(-1)}dl{display:grid;gap:.25rem;margin-block-end:0;font-size:.8rem}dl div{display:flex;flex-wrap:wrap;justify-content:space-between;gap:.25rem 1rem;min-inline-size:0}dd{margin-inline-start:0;overflow-wrap:anywhere}dt{font-weight:700}.semantics{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,18rem),1fr));gap:1rem}.semantics section{padding:1rem;border:2px solid currentColor;border-radius:.75rem}.controls{display:flex;flex-wrap:wrap;gap:.75rem}.controls button{display:inline-flex;align-items:center;gap:.5rem;min-block-size:2.75rem;padding:.5rem .75rem;border:2px solid currentColor;border-radius:.5rem;background:transparent;color:inherit;font:inherit}.controls .icon{inline-size:1.25rem;block-size:1.25rem}.named-reference{display:flex;flex-wrap:wrap;align-items:center;gap:.75rem}.named-reference .icon{inline-size:2.5rem;block-size:2.5rem}.missing{display:grid;place-items:center;min-block-size:4rem;border:2px dashed currentColor;border-radius:.5rem;font-weight:700}.visually-hidden{position:absolute;inline-size:1px;block-size:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0}@media(max-width:24rem){main{padding:.75rem}.theme{padding:.75rem}.sample-grid{grid-template-columns:1fr}}@media(forced-colors:active){body,.theme{background:Canvas;color:CanvasText}.theme,.icon-card,.sample,.semantics section,.controls button,.missing{border-color:CanvasText}.icon{color:CanvasText;forced-color-adjust:auto}}
main>*,.semantics>*{min-inline-size:0}.controls button{max-inline-size:100%;white-space:normal;overflow-wrap:anywhere}.named-reference figcaption{min-inline-size:0;overflow-wrap:anywhere}
</style>
</head>
<body>
<svg class="visually-hidden" aria-hidden="true" focusable="false"><defs>${symbols}</defs></svg>
<main>
<header><p>Private Phase 5D-A proof</p><h1>Icon review index</h1><p class="intro">Geometry is shown at compact, standard, and prominent sizes in both reading directions. Text identifies every state so review never depends on icon recognition or color.</p></header>
${themeReview(catalog, 'light')}
${themeReview(catalog, 'dark')}
<div class="semantics">
<section aria-labelledby="named-heading"><h2 id="named-heading">Named reference</h2><figure class="named-reference"><svg class="icon" data-direction="${arrow.direction}" viewBox="0 0 24 24" role="img" aria-labelledby="named-title named-description" focusable="false"><title id="named-title">Inline-start arrow reference</title><desc id="named-description">A tooling reference that mirrors in right-to-left layouts.</desc><use href="#p5d-icon-${arrow.id}" /></svg><figcaption>Reference only; application meaning still requires text.</figcaption></figure></section>
<section aria-labelledby="control-heading"><h2 id="control-heading">Owning controls</h2><div class="controls"><button type="button"><svg class="icon" data-direction="${refresh.direction}" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><use href="#p5d-icon-${refresh.id}" /></svg><span>Refresh records</span></button><button type="button"><svg class="icon" data-direction="${menu.direction}" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><use href="#p5d-icon-${menu.id}" /></svg><span>Open navigation</span></button><button type="button"><svg class="icon" data-direction="${close.direction}" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><use href="#p5d-icon-${close.id}" /></svg><span>Close review</span></button></div></section>
<section aria-labelledby="absent-heading"><h2 id="absent-heading">Icon-absent task</h2><p>Every task remains explicit when icons are unavailable.</p><div class="controls"><button type="button">Refresh records</button><button type="button">Open navigation</button><button type="button">Close review</button></div></section>
<section aria-labelledby="missing-heading"><h2 id="missing-heading">Missing preview</h2><div class="missing" role="img" aria-label="Preview unavailable for requested icon">Unavailable preview</div></section>
</div>
</main>
</body>
</html>
`;
}

export function generateIconArtifacts(input: unknown): GeneratedIconArtifacts {
  const catalog = [...validateIconCatalog(input)].sort((left, right) =>
    compareText(left.id, right.id),
  );
  const sourceFingerprint = sha256(canonicalJson(catalog));
  const runtimeCatalog = runtimeCatalogSource(catalog);
  const reviewIndex = reviewIndexHtml(catalog);
  const sourceManifest = canonicalJson({
    catalogSchemaVersion: 1,
    iconCount: catalog.length,
    icons: catalog.map((icon) => ({
      direction: icon.direction,
      fingerprint: sha256(canonicalJson(icon)),
      id: icon.id,
    })),
    sourceFingerprint,
  });
  const outputManifest = canonicalJson({
    artifacts: [
      {
        bytes: Buffer.byteLength(runtimeCatalog),
        name: 'runtime-catalog.ts',
        sha256: sha256(runtimeCatalog),
      },
      {
        bytes: Buffer.byteLength(reviewIndex),
        name: 'review-index.html',
        sha256: sha256(reviewIndex),
      },
      {
        bytes: Buffer.byteLength(sourceManifest),
        name: 'source-manifest.json',
        sha256: sha256(sourceManifest),
      },
    ],
    generator: 'phase-5d-icon-tooling',
    generatorSchemaVersion: 1,
    sourceFingerprint,
  });

  return Object.freeze({
    'runtime-catalog.ts': runtimeCatalog,
    'review-index.html': reviewIndex,
    'source-manifest.json': sourceManifest,
    'output-manifest.json': outputManifest,
  });
}

export function detectGeneratedArtifactDrift(
  actual: Readonly<Record<string, string>>,
  expected: GeneratedIconArtifacts,
): readonly ArtifactDrift[] {
  const expectedNames = new Set<string>(generatedArtifactNames);
  const drift: ArtifactDrift[] = [];

  for (const artifact of generatedArtifactNames) {
    if (!Object.hasOwn(actual, artifact)) drift.push({ artifact, kind: 'missing' });
    else if (actual[artifact] !== expected[artifact]) drift.push({ artifact, kind: 'changed' });
  }
  for (const artifact of Object.keys(actual).sort(compareText)) {
    if (!expectedNames.has(artifact)) drift.push({ artifact, kind: 'unexpected' });
  }

  return Object.freeze(drift);
}
